public static int countOilDeposits(char[][] grid) {
    // initialize the number of oil deposits to 0
    int numOilDeposits = 0;

    // loop through each row of the grid
    for (int i = 0; i < grid.length; i++) {
        // loop through each column of the grid
        for (int j = 0; j < grid[i].length; j++) {
            // if the current cell contains an oil pocket (@)
            if (grid[i][j] == '@') {
                // increment the number of oil deposits
                numOilDeposits++;
                // mark the oil deposit as visited
                grid[i][j] = '*';
                // recursively explore the surrounding cells
                exploreSurroundingCells(grid, i, j);
            }
        }
    }

    // return the number of oil deposits
    return numOilDeposits;
}

// explore the surrounding cells for an unvisited oil pocket
private static void exploreSurroundingCells(char[][] grid, int i, int j) {
    // check if the cell to the left is an unvisited oil pocket
    if (j > 0 && grid[i][j - 1] == '@') {
        grid[i][j - 1] = '*';
        exploreSurroundingCells(grid, i, j - 1);
    }
    // check if the cell to the right is an unvisited oil pocket
    if (j < grid[i].length - 1 && grid[i][j + 1] == '@') {
        grid[i][j + 1] = '*';
        exploreSurroundingCells(grid, i, j + 1);
    }
    // check if the cell above is an unvisited oil pocket
    if (i > 0 && grid[i - 1][j] == '@') {
        grid[i - 1][j] = '*';
        exploreSurroundingCells(grid, i - 1, j);
    }
    // check if the cell below is an unvisited oil pocket
    if (i < grid.length - 1 && grid[i + 1][j] == '@') {
        grid[i + 1][j] = '*';
        exploreSurroundingCells(grid, i + 1, j);
    }
}
