public static int countOilDeposits(char[][] grid) {
    // Initialize a set to store the visited cells
    Set<String> visited = new HashSet<>();
    // Initialize a variable to store the number of oil deposits
    int count = 0;

    // Loop through each cell in the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell is an oil pocket and has not been visited before
            if (grid[i][j] == '@' && !visited.contains(i + "," + j)) {
                // Visit the current cell and its adjacent cells recursively
                count += visitOilDeposit(grid, visited, i, j);
            }
        }
    }

    // Return the number of oil deposits
    return count;
}

// Recursive function to visit the current cell and its adjacent cells
private static int visitOilDeposit(char[][] grid, Set<String> visited, int i, int j) {
    // If the current cell is not an oil pocket or has been visited before, return 0
    if (grid[i][j] != '@' || visited.contains(i + "," + j)) {
        return 0;
    }

    // Mark the current cell as visited
    visited.add(i + "," + j);

    // Recursively visit the adjacent cells
    int count = 0;
    if (i > 0) { count += visitOilDeposit(grid, visited, i - 1, j); }
    if (i < grid.length - 1) { count += visitOilDeposit(grid, visited, i + 1, j); }
    if (j > 0) { count += visitOilDeposit(grid, visited, i, j - 1); }
    if (j < grid[i].length - 1) { count += visitOilDeposit(grid, visited, i, j + 1); }

    // Return the number of oil deposits visited during the recursion
    return 1 + count;
}
