public String sortString(String s) {
    char[] chars = s.toCharArray();
    char[] sortedChars = new char[chars.length];
    int i = 0, j = 0;

    // step 1: sort smallest to largest
    Arrays.sort(chars);

    // step 2-4: sort smallest to largest while considering duplicates
    while (i < chars.length) {
        char c = chars[i];
        int count = 0;
        for (int k = i; k < chars.length; k++) {
            if (chars[k] == c) {
                count++;
            }
        }
        if (count == 1) {
            sortedChars[j++] = c;
        } else {
            for (int k = i; k < chars.length; k++) {
                if (chars[k] == c) {
                    sortedChars[j++] = c;
                    count--;
                    if (count == 0) {
                        break;
                    }
                }
            }
        }
        i++;
    }

    // step 5-7: sort largest to smallest while considering duplicates
    i = chars.length - 1;
    while (i > -1) {
        char c = chars[i];
        int count = 0;
        for (int k = i; k > -1; k--) {
            if (chars[k] == c) {
                count++;
            }
        }
        if (count == 1) {
            sortedChars[j++] = c;
        } else {
            for (int k = i; k > -1; k--) {
                if (chars[k] == c) {
                    sortedChars[j++] = c;
                    count--;
                    if (count == 0) {
                        break;
                    }
                }
            }
        }
        i--;
    }

    return String.valueOf(sortedChars);
}
