    for (i = 0; i < 10; i++) {
        if (digits[i] == 0) {
            possible = false;
            break;
        }
    }
    if (!possible) {
        return -1;
    }

    // generate all possible combinations of digits
    for (i = 0; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = smallest * 10 + i;
            digits[i]--;
        }
    }

    return smallest;
}
