public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    while (n > 0) {
        int nextSquare = (int) Math.sqrt(n);
        minSquares++;
        n -= nextSquare * nextSquare;
    }
    return minSquares;
}
